import{z as r,x as c,o as l,c as s,q as n,j as d,D as a,d as E,s as i,S as t,b as o}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"NCCL 调优","description":"","frontmatter":{"title":"NCCL 调优","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/nccl-tuning.md","filePath":"llm/nccl-tuning.md","lastUpdated":1791413859000}'),B={name:"llm/nccl-tuning.md"};function p(C,e,L,N,m,D){const A=c("Mermaid");return l(),s("div",null,[e[2]||(e[2]=n('<h1 id="nccl-调优" tabindex="-1">NCCL 调优 <a class="header-anchor" href="#nccl-调优" aria-label="Permalink to &quot;NCCL 调优&quot;">​</a></h1><div class="epigraph"><p>集合通信库按拓扑选环或树、按体积切块；推理的小消息若仍走训练默认，启动开销会把 TP 的短 All-Reduce 变成逐步主项。</p><footer>—— NVIDIA NCCL 用户指南中的算法、协议与拓扑探测；训练侧大块梯度与推理短激活要分开调</footer></div><p><a href="/llm/tp-comm-overlap">上一课</a>假设通信原语已经够快，才谈得上重叠。本课写仍走 NCCL 时的旋钮：算法（Ring/Tree）、协议（LL/LL128/Simple）、通道数、缓冲。自定义 AR 覆盖不了的跨节点、大 prefill、以及 MoE 的 all-to-all，还得靠 NCCL。后课 MoE 批处理会再碰到 all-to-all；这里先把稠密 TP 的 All-Reduce 调完。不把环形算法的推导再写一遍，那是下一课程「通信与集群」的主干。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>NCCL 默认面向训练：大块、延迟可被计算藏住。推理 decode 的 All-Reduce 体积小、频率等于层数×token。默认 Simple 协议带宽好、延迟差；LL 协议延迟好、大块带宽差。缺口是按消息体积分派协议，并固定拓扑探测结果，避免每次建组都重新扫 NVLink。<code>NCCL_P2P_LEVEL</code>、<code>NCCL_IB_DISABLE</code>、网卡绑定在多节点上决定你以为的 NVLink 域是否其实绕了 PCI 或 NIC。</p><p><span class="marginnote">decode 与 prefill 是推理的两个阶段：prefill 一次吞下整段 prompt，消息大、比的是带宽；decode 一个 token 一个 token 往外蹦，每步只同步很小的激活，比的是延迟。同一个模型，两阶段的最优协议可以完全相反——这就是推理服务要按阶段分派协议的原因。</span></p><p>错误 NUMA / GPU-NIC 亲和会让「调了 LL 仍然慢」。先确认拓扑，再改算法字符串。</p><p><span class="marginnote">CUDA Graph 与 NCCL 的兼容随版本变：捕获期间禁止的操作、是否支持用户缓冲，要以当前 NCCL 文档为准，不要抄两年前进程的环境变量表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对目标消息大小做微基准：All-Reduce 延迟 vs bytes。decode 点落在延迟平台，应试 LL/LL128；prefill 点落在带宽斜坡，用 Simple。通道数过多会把小消息切得更碎。固定 <code>NCCL_ALGO</code> / <code>NCCL_PROTO</code> 做 A/B，但只在已验证拓扑上。与自定义 AR 分派：体积小于阈值走自定义，否则 NCCL——阈值由这张微基准定，不要写死 1MB 当宇宙常数。</p><p>环境变量在进程启动时读。与<a href="/llm/kernel-autotuning">内核自动调优</a>一样，按 SKU 与节点形状存一份已知好的配置，不要每容器靠默认。</p>',11)),(l(),d(t,null,{default:a(()=>[i(A,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TOPO%5B%22%E7%A1%AE%E8%AE%A4%20NVLink%20%2F%20NIC%20%E6%8B%93%E6%89%91%22%5D%20--%3E%20BENCH%5B%22All-Reduce%20%E5%BB%B6%E8%BF%9F-%E4%BD%93%E7%A7%AF%E6%9B%B2%E7%BA%BF%22%5D%0A%20%20BENCH%20--%3E%20DEC%5B%22decode%3A%20%E4%BD%8E%E5%BB%B6%E8%BF%9F%E5%8D%8F%E8%AE%AE%22%5D%0A%20%20BENCH%20--%3E%20PRE%5B%22prefill%3A%20%E5%B8%A6%E5%AE%BD%E5%8D%8F%E8%AE%AE%22%5D%0A%20%20BENCH%20--%3E%20SPLIT%5B%22%E9%98%88%E5%80%BC%3A%20%E8%87%AA%E5%AE%9A%E4%B9%89%20AR%20vs%20NCCL%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[E(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=o("h2",{id:"机制",tabindex:"-1"},[E("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=o("p",null,"Ring 的延迟随 rank 数线性，Tree 的延迟随层数对数；小规模 NVLink 域两者都可能被启动开销淹没。调优改的是常数项与切块，不改集合通信的渐近。重叠课要求通信走单独流：NCCL 默认流与计算流的同步点要显式，否则调了协议也看不到重叠。",-1)),(l(),d(t,null,{default:a(()=>[i(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEC%5B%22decode%20%E6%AF%8F%E6%AD%A5%3A%20%E6%AF%8F%E5%B1%82%E9%83%BD%E5%81%9A%E5%B0%8F%20All-Reduce%22%5D%20--%3E%20SMALL%5B%22%E6%AF%8F%E6%9D%A1%E6%B6%88%E6%81%AF%E4%BB%85%E5%87%A0%E7%99%BE%20KB%22%5D%0A%20%20SMALL%20--%3E%20OVH%5B%22%E5%90%AF%E5%8A%A8%E5%BC%80%E9%94%80%20%CE%B1%20%E5%8D%A0%E5%A4%A7%E5%A4%B4%22%5D%0A%20%20OVH%20--%3E%20FIX%5B%22%E6%8D%A2%20LL%20%2F%20LL128%20%E5%8E%8B%20%CE%B1%22%5D%0A%20%20OVH%20--%3E%20OVERLAP%5B%22%E6%88%96%E4%B8%8E%E8%AE%A1%E7%AE%97%E9%87%8D%E5%8F%A0%E8%97%8F%E4%BD%8F%E9%80%9A%E4%BF%A1%22%5D%0A%20%20FIX%20--%3E%20WIN%5B%22%E7%AB%AF%E5%88%B0%E7%AB%AF%E6%AF%8F%E6%AD%A5%E5%BB%B6%E8%BF%9F%E4%B8%8B%E9%99%8D%22%5D%0A%20%20OVERLAP%20--%3E%20WIN%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[E(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=n('<p><span class="marginnote">代个数字看频率的杀伤力：TP=8 时每层约 2 次 All-Reduce，32 层模型每步就是 64 次调用；若每次固定开销 80 微秒，光「启动」就吃掉约 5.1 毫秒——消息本身可能只占零头。这就是 decode 场景必须压 \\(\\alpha\\) 或做重叠的算术。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要在生产用 <code>NCCL_DEBUG=INFO</code> 常开。不要把单机 TP=8 的配置拷到跨节点 TP=8。安全：环境变量属于部署契约，应进版本控制。下一课：MoE 推理里专家 token 的批怎么凑。</p><p><span class="marginnote">初学者容易以为「调优 = 改算法字符串」。顺序错了就全白调：NUMA 绑错或 P2P 被禁时，库以为自己在 NVLink 上跑环，数据实际绕了 PCIe——任何算法名都救不回来。所以本文反复强调：先读拓扑探测结果，再动 <code>NCCL_ALGO</code>。</span></p><p>出处：NVIDIA NCCL 文档。算法课序见后续 Ring/Tree 专文。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>decode 小 All-Reduce 要低延迟协议；大块用带宽协议。</li><li>先拓扑与亲和，再改 <code>ALGO</code>/<code>PROTO</code>。</li><li>用延迟-体积曲线定自定义 AR 的阈值。</li><li>CUDA Graph 兼容性随 NCCL 版本变。</li><li>配置按 SKU 固化，不要靠默认。</li><li>下一课：MoE 推理批处理。</li><li>出处：NVIDIA NCCL 用户指南。</li></ul>',7))])}const h=r(B,[["render",p]]);export{_ as __pageData,h as default};
